import java.io.*;import java.nio.file.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.dexbacked.*;
public class InventoryTypes {public static void main(String[] a)throws Exception{Set<String> defs=new TreeSet<>(),refs=new TreeSet<>();var z=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));for(String n:z.getDexEntryNames()){DexBackedDexFile d=(DexBackedDexFile)z.getEntry(n).getDexFile();for(ClassDef c:d.getClasses()){defs.add(c.getType());if(c.getType().equals("Lawuh;"))System.out.println("AWUH_DEFINED "+n);}for(var t:d.getTypeReferences()){String s=t.getType();while(s.startsWith("["))s=s.substring(1);if(s.startsWith("L"))refs.add(s);}}Files.write(Paths.get(a[1]+".defs"),defs);refs.removeAll(defs);Files.write(Paths.get(a[1]+".missing"),refs);System.out.println(a[0]+" defs="+defs.size()+" unresolvedTypes="+refs.size());}}
